 403	pub fn queueWrite(
 404	    self: *Exec,
 405	    alloc: Allocator,
 406	    td: *termio.Termio.ThreadData,
 407	    data: []const u8,
 408	    linefeed: bool,
 409	) !void {
 410	    _ = self;
 411	    const exec = &td.backend.exec;
 412	
 413	    // If our process is exited then we don't send any more writes.
 414	    if (exec.exited) return;
 415	
 416	    // We go through and chunk the data if necessary to fit into
 417	    // our cached buffers that we can queue to the stream.
 418	    var i: usize = 0;
 419	    while (i < data.len) {
 420	        const w = try exec.write_pool.create(alloc);
 421	        w.td = exec;
 422	        const buf = &w.buf;
 423	        const slice = slice: {
 424	            // The maximum end index is either the end of our data or
 425	            // the end of our buffer, whichever is smaller.
 426	            const max = @min(data.len, i + buf.len);
 427	
 428	            // Fast
 429	            if (!linefeed) {
 430	                fastmem.copy(u8, buf, data[i..max]);
 431	                const len = max - i;
 432	                i = max;
 433	                break :slice buf[0..len];
 434	            }
 435	
 436	            // Slow, have to replace \r with \r\n
 437	            var buf_i: usize = 0;
 438	            while (i < data.len and buf_i < buf.len - 1) {
 439	                const ch = data[i];
 440	                i += 1;
 441	
 442	                if (ch != '\r') {
 443	                    buf[buf_i] = ch;
 444	                    buf_i += 1;
 445	                    continue;
 446	                }
 447	
 448	                // CRLF
 449	                buf[buf_i] = '\r';
 450	                buf[buf_i + 1] = '\n';
 451	                buf_i += 2;
 452	            }
 453	
 454	            break :slice buf[0..buf_i];
 455	        };
 456	
 457	        //for (slice) |b| log.warn("write: {x}", .{b});
 458	
 459	        exec.write_stream.queueWrite(
 460	            td.loop,
 461	            &exec.write_queue,
 462	            &w.req,
 463	            .{ .slice = slice },
 464	            ThreadData.Write,
 465	            w,
 466	            ttyWrite,
 467	        );
 468	    }
 587	const Subprocess = struct {
 588	    const c = @import("posix_c");
 589	
 590	    arena: std.heap.ArenaAllocator,
 591	    cwd: ?[:0]const u8,
 592	    env: ?EnvMap,
 593	    args: []const [:0]const u8,
 594	    grid_size: renderer.GridSize,
 595	    screen_size: renderer.ScreenSize,
 596	    pty: ?Pty = null,
 597	    process: ?Process = null,
 598	
 599	    rt_pre_exec_info: Command.RtPreExecInfo,
 600	    rt_post_fork_info: Command.RtPostForkInfo,
 601	
 602	    /// Union that represents the running process type.
 603	    const Process = union(enum) {
 604	        /// Standard POSIX fork/exec
 605	        fork_exec: Command,
 606	
 607	        /// Flatpak DBus command
 608	        flatpak: FlatpakHostCommand,
 609	    };
 610	
 611	    const ArgsFormatter = struct {
 612	        args: []const [:0]const u8,
 613	
 614	        pub fn format(this: @This(), writer: *std.Io.Writer) std.Io.Writer.Error!void {
 615	            for (this.args, 0..) |a, i| {
 616	                if (i > 0) try writer.writeAll(", ");
 617	                try writer.print("`{s}`", .{a});
 618	            }
 619	        }
 620	    };
